/**
 * Parity test: the TypeScript port must reproduce the real Python engine.
 * engine-golden.json was generated by running backend/app/adaptive/engine.py
 * (decide_strategy + signals_for_level, ENGINE_VERSION 1.2.0) from the main repository.
 */
import golden from "./engine-golden.json";
import { COLD_START_PRIOR, FAMILY_WEIGHTS, decideStrategy, signalsForLevel, type LearnerPreferences, type LearnerSignals } from "@/lib/engine";

type Case = { name: string; signals: LearnerSignals; prefs: LearnerPreferences; expected: Record<string, unknown> };

describe("engine port matches the Python engine", () => {
  it.each((golden as Case[]).map((c) => [c.name, c] as const))("%s", (_name, c) => {
    const s = decideStrategy(c.signals, c.prefs);
    for (const [key, want] of Object.entries(c.expected)) {
      const got = s[key as keyof typeof s];
      if (typeof want === "number") expect(got as number).toBeCloseTo(want, 3);
      else expect(got).toEqual(want);
    }
  });

  it("signalsForLevel reproduces the Python signal profiles", () => {
    for (const c of golden as Case[]) {
      const m = /^level-(\d+)$/.exec(c.name);
      if (!m) continue;
      const ts = signalsForLevel(Number(m[1]));
      for (const [k, v] of Object.entries(c.signals)) {
        if (typeof v === "number") expect(ts[k as keyof LearnerSignals] as number).toBeCloseTo(v, 6);
        else expect(ts[k as keyof LearnerSignals]).toEqual(v);
      }
    }
  });
});

describe("engine invariants", () => {
  it("family weights sum to 1", () => {
    expect(Object.values(FAMILY_WEIGHTS).reduce((a, b) => a + b, 0)).toBeCloseTo(1, 10);
  });

  it("a brand-new learner sits on the supportive prior", () => {
    expect(decideStrategy({ ...signalsForLevel(50), attempts: 0 }).support_score).toBeCloseTo(COLD_START_PRIOR, 3);
  });

  it("more ability never means more support", () => {
    let prev = Infinity;
    for (let lvl = 0; lvl <= 100; lvl += 5) {
      const s = decideStrategy(signalsForLevel(lvl)).support_score;
      expect(s).toBeLessThanOrEqual(prev + 1e-9);
      prev = s;
    }
  });

  it("drops a missing ML family and re-normalises the weights", () => {
    const s = decideStrategy({ ...signalsForLevel(40), struggle_probability: null });
    expect(s.factors.map((f) => f.family)).not.toContain("ml_struggle");
    expect(s.factors.reduce((a, f) => a + f.weight, 0)).toBeCloseTo(1, 2);
  });
});
